/**
 * Global quantity selector web component.
 *
 * Usage:
 * This component is designed to manage the quantity of items for products on an e-commerce platform.
 * It listens to user interactions to increment or decrement the quantity value.
 * Ensure to provide the necessary HTML structure when deploying this component.
 *
 */

class QuantitySelector extends HTMLElement {
  private minusButton: HTMLButtonElement | null;
  private plusButton: HTMLButtonElement | null;
  private quantityInput: HTMLInputElement | null;

  constructor() {
    super();

    this.minusButton = this.querySelector("[js-quantity-selector='minus']");
    this.plusButton = this.querySelector("[js-quantity-selector='plus']");
    this.quantityInput = this.querySelector("[js-quantity-selector='input']");
  }

  connectedCallback() {
    if (!this.minusButton || !this.plusButton || !this.quantityInput) {
      console.error(
        "QuantitySelector: Missing required elements in the component.",
      );

      return;
    }

    this.minusButton.addEventListener("click", () => {
      if (this.quantityInput) this.adjustQuantity(this.quantityInput, -1);
    });
    this.plusButton.addEventListener("click", () => {
      if (this.quantityInput) this.adjustQuantity(this.quantityInput, 1);
    });
  }

  private adjustQuantity(input: HTMLInputElement, adjustment: number) {
    const currentVal = Number(input.value);
    const newCount = currentVal + adjustment;

    if (newCount >= Number(input.min)) {
      input.value = newCount.toString();

      const variantId = input.dataset.id;
      if (variantId) {
        this.dispatchEvent(
          new CustomEvent("quantityChanged", {
            bubbles: true,
            detail: { variantId, quantity: newCount },
          }),
        );
      }
    }
  }
}

customElements.define("uwp-quantity-selector", QuantitySelector);
